// FindPage reads a page of the OrderLine rows filter finds, in the
// sort's order, after the key of the page before (D60, amended).
func (r *OrderLineSQLiteRepository) FindPage(ctx context.Context, filter *OrderLineFilter, opts *OrderLinePageOptions) (*OrderLinePage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of OrderLine rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = OrderLineSortById
	}
	column, ok := orderLineSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: OrderLine sorts by id, quantity and note, not %q", string(field))
	}
	var after any
	if opts.After != nil {
		if _, err := opts.After.arg(); err != nil {
			return nil, err
		}
		key, err := orderLineSQLite.keyArg(opts.After.Id)
		if err != nil {
			return nil, err
		}
		after = key
	}
	var args []any
	conditions := filter.sqliteConditions(&args)
	records, err := orderLineSQLite.page(ctx, r.q(), conditions, args, sqliteSort{sql: column.sql, key: column.key, nulls: column.nulls}, field == OrderLineSortById, opts.Sort.Desc, after, limit, opts.IncludeDeleted)
	if err != nil {
		return nil, err
	}
	// Next is the key of the page's last row, so the page reads its
	// primary key whatever Fields selects.
	fields := opts.Fields
	fields.Id = true
	rows, err := r.decode(ctx, records, fields, true)
	if err != nil {
		return nil, err
	}
	page := &OrderLinePage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = orderLinePageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

