// CreateMany inserts the rows, in order, a row at a time, in one
// transaction: a VALUES list on SQLite takes no DEFAULT.
func (r *OrderLineSQLiteRepository) CreateMany(ctx context.Context, inputs []*types.OrderLine) ([]*types.OrderLine, error) {
	out := make([]*types.OrderLine, 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	err := r.within(ctx, func(q sqliteQuerier) error {
		in := &OrderLineSQLiteRepository{db: r.db, tx: q.(*sql.Tx)}
		for _, input := range inputs {
			row, err := in.CreateOne(ctx, input)
			if err != nil {
				return err
			}
			out = append(out, row)
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

// sets are update's assignments, each value appended to args after those
// already there, and the columns they set and their values, which an
// upsert only if changed compares (D89).
func (r *OrderLineSQLiteRepository) sets(update *OrderLineUpdate, args *[]any) (sets, compare, next []string, err error) {
	if update == nil {
		return nil, nil, nil, nil
	}
	if update.OrderID != nil {
		value, err := orderLineSQLite.arg(*update.OrderID, 1)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`order_id = ?%d`, len(*args)))
		compare, next = append(compare, `order_line.order_id`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.ProductID != nil && update.ProductIDSetNull {
		return nil, nil, nil, fmt.Errorf("product_id cannot be updated with both value and null assignment")
	}
	if update.ProductIDSetNull {
		sets = append(sets, `product_id = NULL`)
		compare, next = append(compare, `order_line.product_id`), append(next, `NULL`)
	} else if update.ProductID != nil {
		value, err := orderLineSQLite.arg(*update.ProductID, 2)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`product_id = ?%d`, len(*args)))
		compare, next = append(compare, `order_line.product_id`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.Quantity != nil {
		value, err := orderLineSQLite.arg(*update.Quantity, 3)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`quantity = ?%d`, len(*args)))
		compare, next = append(compare, `order_line.quantity`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	if update.Note != nil && update.NoteSetNull {
		return nil, nil, nil, fmt.Errorf("note cannot be updated with both value and null assignment")
	}
	if update.NoteSetNull {
		sets = append(sets, `note = NULL`)
		compare, next = append(compare, `order_line.note`), append(next, `NULL`)
	} else if update.Note != nil {
		value, err := orderLineSQLite.arg(*update.Note, 4)
		if err != nil {
			return nil, nil, nil, err
		}
		*args = append(*args, value)
		sets = append(sets, fmt.Sprintf(`note = ?%d`, len(*args)))
		compare, next = append(compare, `order_line.note`), append(next, fmt.Sprintf("?%d", len(*args)))
	}
	return sets, compare, next, nil
}

